#[derive(Clone, Debug)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub struct Loops {
    pub b1_supply_response: f64,
    pub b2_backlash: f64,
    pub b3_affordability: f64,
    pub r1_recursive_ai: f64,
    pub r2_robot_bootstrap: f64,
    pub r3_capex_momentum: f64,
    pub b4_credit: f64,
    /// R4: post-singularity physical acceleration — ASI compresses
    /// engineering/commissioning delays, raises scaling ceilings, and
    /// dissolves robot-integration friction. Physics (materials, curing,
    /// forging) still binds; cognitive work hidden inside construction
    /// timelines does not.
    pub r4_physical_acceleration: f64,
    /// Society layer master switch: endogenous political economy
    /// (sentiment, transfers, regulation, labor power, trust). With 0.0
    /// the legacy constant-gain B2 behavior is exactly recovered.
    pub society_layer: f64,
    /// Demography layer switch: dynamic pools, hiring-freeze signal
    /// filter, youth blockage, care economy, migration/solidarity/tension
    /// politics. With 0.0 the static-pool legacy is exactly recovered.
    pub d_demography: f64,
    /// R5: Wright-law launch learning -> orbital-compute gate. With 0.0
    /// (and orbital_effectiveness 0) the terrestrial-only legacy is
    /// exactly recovered.
    pub r5_launch_learning: f64,
    /// B11: endogenous long rate / bond-market pricing of the transfer
    /// ramp. With 0.0 rates stay exogenous (legacy flat 12% DCF world).
    pub b11_endogenous_rates: f64,
}

impl Default for Loops {
    fn default() -> Self {
        Loops {
            b1_supply_response: 1.0,
            b2_backlash: 1.0,
            b3_affordability: 1.0,
            r1_recursive_ai: 1.0,
            r2_robot_bootstrap: 1.0,
            r3_capex_momentum: 1.0,
            b4_credit: 1.0,
            r4_physical_acceleration: 1.0,
            society_layer: 1.0,
            d_demography: 1.0,
            r5_launch_learning: 1.0,
            b11_endogenous_rates: 1.0,
        }
    }
}

#[derive(Clone, Debug)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
